(async function(){
// UTF-8対応デコード
const drafts=JSON.parse(new TextDecoder().decode(Uint8Array.from(atob(""),c=>c.charCodeAt(0))));
const uid=507372116;
let ok=0,fail=0;
for(const d of drafts){
try{
const r=await fetch("/api/v1/drafts",{method:"POST",credentials:"include",headers:{"Content-Type":"application/json"},body:JSON.stringify({draft_title:d.title,draft_subtitle:"",draft_body:d.proseMirror,draft_bylines:[{id:uid,is_guest:false}],draft_podcast_url:null,draft_podcast_duration:null,draft_section_id:null,section_chosen:false})});
const j=await r.json();
if(j.id){console.log("OK",d.title);ok++;}
else{console.log("NG",d.title,JSON.stringify(j).slice(0,100));fail++;}
}catch(e){console.log("ERR",d.title,e.message);fail++;}
await new Promise(r=>setTimeout(r,1500));
}
console.log("完了 OK:"+ok+" NG:"+fail);
if(ok>0)console.log("確認: https://senryaku.substack.com/publish/drafts");
})();